package com.cyclecare.app
import com.cyclecare.app.data.local.rust.RustTrackNative
import org.junit.Assert.*
import org.junit.Test
class RemoteStorageJniBoundaryTest{
 open class Probe(val size:Int=2,val branch:Int=0,val cut:Int=0,val error:Throwable=IllegalStateException("sentinel"),val initial:Long=0,val remoteValue:Long=3,val seq:Long=5,val localValue:Long=7){val trace=mutableListOf<String>();private val thread=Thread.currentThread();private fun hit(s:String){assertSame(thread,Thread.currentThread());trace+=s;if(trace.size==cut)throw error};open fun ready():Int{hit("ready");return size};fun cursor():Long{hit("cursor");return initial};fun remote(i:Int):Long{hit("remote$i");return remoteValue};fun sequence(i:Int):Long{hit("sequence$i");return seq+i};fun inspect(i:Int){hit("inspect$i")};fun server(i:Int):Long{hit("server$i");return if(branch==2)3 else 1};fun pending(i:Int):Boolean{hit("pending$i");return branch==1};fun conflict(i:Int){hit("conflict$i")};fun prepare(i:Int){hit("prepare$i")};fun local(i:Int):Long{hit("local$i");return localValue};fun domain(i:Int){hit("domain$i")};fun revision(i:Int,n:Long){assertEquals(localValue+1,n);hit("revision$i")};fun advance(i:Int,n:Long){assertEquals(seq+i,n);hit("advance$i")}}
 @Test fun exactAllThreeBranchesOrderAndEveryThrowableCutoff(){RustTrackNative.warmUp();for(branch in 0..2){val p=Probe(branch=branch);assertEquals(if(branch==0)2 else 0,RustTrackNative.remoteDriver(p));val expected=mutableListOf("ready","cursor");for(i in 0..1){expected+=listOf("remote$i","sequence$i","inspect$i","server$i");if(branch!=2){expected+="pending$i";expected+=if(branch==1)listOf("conflict$i")else listOf("prepare$i","local$i","domain$i","revision$i")};expected+="advance$i"};assertEquals(expected,p.trace);for(error in listOf(IllegalArgumentException("sentinel"),ArithmeticException("sentinel"),kotlinx.coroutines.CancellationException("sentinel"),AssertionError("sentinel")))for(cut in 1..expected.size){val q=Probe(branch=branch,cut=cut,error=error);assertSame(error,runCatching{RustTrackNative.remoteDriver(q)}.exceptionOrNull());assertEquals(expected.take(cut),q.trace)}}}
 @Test fun boundariesInvalidSequenceOverflowEmptyHundredAndNoGlobalMonitor(){RustTrackNative.warmUp();for(n in listOf(0,1,100)){val p=Probe(size=n);assertEquals(n,RustTrackNative.remoteDriver(p))};for(n in listOf(-1,101)){val p=Probe(size=n);assertTrue(runCatching{RustTrackNative.remoteDriver(p)}.exceptionOrNull()is IllegalArgumentException);assertEquals(listOf("ready"),p.trace)};for(p in listOf(Probe(remoteValue=0),Probe(seq=0))){assertTrue(runCatching{RustTrackNative.remoteDriver(p)}.exceptionOrNull()is IllegalArgumentException);assertEquals(listOf("ready","cursor","remote0","sequence0"),p.trace)};val p=Probe(localValue=Long.MAX_VALUE);val e=runCatching{RustTrackNative.remoteDriver(p)}.exceptionOrNull();assertTrue(e is ArithmeticException);assertEquals("long overflow",e?.message);assertEquals("local0",p.trace.last());for(local in listOf(Long.MIN_VALUE,-1L,Long.MAX_VALUE-1)){assertEquals(2,RustTrackNative.remoteDriver(Probe(localValue=local,initial=Long.MIN_VALUE)))};assertTrue(runCatching{RustTrackNative.remoteDriver(Any())}.exceptionOrNull()is NoSuchMethodError);val q=object:Probe(){override fun ready():Int{val latch=java.util.concurrent.CountDownLatch(1);val t=Thread{synchronized(RustTrackNative){latch.countDown()}};t.start();assertTrue(latch.await(2,java.util.concurrent.TimeUnit.SECONDS));t.join();return super.ready()}};assertEquals(2,RustTrackNative.remoteDriver(q))}
}
